    edit_faq_q1: "PDF 속 기존 글자나 오탈자를 직접 수정할 수 있나요?",
    edit_faq_a1: "네! 상단 메뉴에서 [기존 텍스트 수정]을 클릭하면 PDF 내부의 모든 텍스트 블록이 자동으로 감지됩니다. 수정하고 싶은 글자를 클릭하면 즉시 입력창이 활성화되어 오탈자 수정, 날짜/이름/금액 변경 등을 손쉽게 수행하실 수 있습니다.",
    edit_faq_q2: "테두리 상자의 크기 조절과 시작/끝점 확인은 어떻게 하나요?",
    edit_faq_a2: "도구함의 [테두리 상자]를 선택한 뒤 페이지 위를 드래그하여 상자를 생성하면, 상자의 좌측 상단(시작점 📍)과 우측 하단(끝점 🏁)에 핸들이 표시됩니다. 4개의 모서리 핸들을 드래그하면 원하는 크기로 정밀하게 리사이징할 수 있으며, 가운데를 잡고 원하는 위치로 자유롭게 이동시킬 수 있습니다.",
    edit_faq_q3: "PDF를 처음 올렸을 때 전체 화면에 맞게 보이게 할 수 있나요?",
    edit_faq_a3: "네! PDF를 업로드하면 자동으로 화면 너비에 맞춘 최적 크기(Fit-To-Width)로 첫 페이지가 즉시 선명하게 렌더링됩니다. 상단 도구 모음의 [너비 맞춤] 또는 [한눈에 보기] 버튼을 통해 언제든 원하는 배율로 화면을 맞추실 수 있습니다.",
    edit_faq_q4: "편집한 내용이 파일에 영구적으로 안전하게 반영되나요?",
