    edit_howto_step2_desc: "Use 'Edit Text' to directly modify words in the PDF, or select Add Text, Border Box, Pen, or Whiteout.",
    edit_howto_step3_title: "Free Move & Resize Boxes",
    edit_howto_step3_desc: "Drag corner handles on added boxes or text to freely resize and adjust start/end coordinates and positions.",
    edit_howto_step4_title: "Finish & Download PDF",
    edit_howto_step4_desc: "Click the download button in the top right to instantly save the finished PDF with all revisions applied.",
    edit_faq_q1: "Can I directly edit existing words or typos in the PDF?",
    edit_faq_a1: "Yes! Click [Edit Text] in the tools menu, and all text blocks inside the PDF are automatically detected. Click any text to open the inline editor and update typos, dates, names, or amounts easily.",
    edit_faq_q2: "How do I resize border boxes and check start/end points?",
    edit_faq_a2: "Select [Border Box] and drag on the page to draw a box. Handles will appear at the top-left (Start 📍) and bottom-right (End 🏁). Drag the 4 corner handles to precisely resize, or drag from the center to move anywhere.",
    edit_faq_q3: "Can I view the PDF fitted to the screen by default?",
    edit_faq_a3: "Yes! When uploaded, the first page is automatically rendered in optimal Fit-To-Width format. You can switch between [Fit Width] and [Fit Page] anytime using the top bar buttons.",
    edit_faq_q4: "Are the edits permanently and securely saved into the file?",
    edit_faq_a4: "Yes! Our high-resolution vector engine merges text, signatures, shapes, and whiteout with the original PDF so it renders crystal-clear in Adobe Acrobat, Chrome, and smartphones.",
